      "conceptExplanation": "「보세화물 장치기간 및 체화관리에 관한 고시」 제6조(반출통고의 주체)상 장치기간 경과화물의 '반출통고' 주체는 보세구역 종류에 따라 세 갈래로 나뉜다. ① '영업용보세창고'에 반입한 물품의 반출통고는 '보세구역운영인'이 화주등(화주·반입자 또는 그 위임을 받은 자)에게 한다. ② '자가용보세창고·보세공장·보세건설장·보세전시장·보세판매장' 및 '보세구역외장치장'에 반입한 물품의 반출통고는 '관할세관장'이 화주등에게 한다. ③ '지정장치장 및 세관지정 보세창고'에 반입한 물품의 반출통고는 '화물관리인'이 화주등에게 한다. 핵심 암기 축은 두 가지다. 첫째 주체 매핑: \\\"영업용보세창고=운영인 / 지정장치장·세관지정 보세창고=화물관리인 / 그 외(자가용·보세공장·보세건설장·보세전시장·보세판매장·보세구역외장치장)=관할세관장\\\". 둘째 통고 시기: 지정장치장·보세창고는 '장치기간 만료 30일 전까지', 보세전시장·보세건설장·보세판매장은 '특허(설영특허)기간 만료시점', 장치기간 2개월 미만 물품(유치·예치물품 등)은 '장치기간 만료시점'(유치·예치 시 매각통고한 경우 생략 가능)에 한다. 주의: 흔히 \\\"특허보세구역=운영인\\\"으로 단순 암기하면 틀린다. 특허보세구역 중 운영인이 통고하는 것은 '영업용보세창고'뿐이며, 같은 특허보세구역인 자가용보세창고·보세공장·보세건설장·보세전시장·보세판매장은 모두 '관할세관장'이 통고한다. 시험에서는 \\\"영업용보세창고만 운영인, 나머지는 관할세관장, 지정장치장·세관지정 보세창고는 화물관리인\\\"이라는 매핑이 정답 키가 된다.",
      "trapAnalysis": "이 유형의 함정은 '주체를 뒤바꾸는 것'에 집중된다. ① 가장 흔한 오답유도는 \\\"지정장치장 반입물품의 반출통고는 세관장이 한다\\\"(2019 no.2 정답='틀린 것')처럼, 화물관리인이 해야 할 것을 세관장으로 바꾼다(지정장치장·세관지정 보세창고=화물관리인이 정답). ② \\\"자가용보세창고 반입물품의 반출통고는 화물관리인이 한다\\\"(2020 no.3 정답='틀린 것')처럼 관할세관장이 통고하는 보세구역을 화물관리인으로 바꿔치기한다. ③ \\\"영업용보세창고는 관할세관장이, 지정장치장은 화물관리인이 통고\\\"(2023 no.20 오답지)처럼 영업용보세창고의 주체를 세관장으로 뒤바꾼다(영업용보세창고=운영인이 정답). ④ 본 대표문항(2024 no.22)은 '주체가 다른 하나'를 묻는 변형으로, 영업용보세창고는 '운영인'이 주체이고 나머지 보세판매장·보세구역외장치장·자가용보세창고·보세공장은 '관할세관장'이 주체여서, 운영인 주체인 영업용보세창고가 정답이다 — \\\"특허보세구역은 다 운영인\\\"이라는 통념을 역이용한 함정이다(실제로는 특허보세구역 중 영업용보세창고만 운영인). ⑤ 시기 함정도 병행된다: \\\"지정장치장·보세창고 반출통고는 장치기간 만료 10일 전까지\\\"(2022 no.25 오답, 정답은 30일 전), \\\"유치·예치물품은 만료 30일 전까지\\\"(2022 no.25·2023 no.20 오답, 정답은 만료시점) 등 30일/10일/만료시점을 섞는다.",
      "answerKey": "[정답 ①] 영업용보세창고. 「보세화물 장치기간 및 체화관리에 관한 고시」 제6조(반출통고의 주체)상, ① '영업용보세창고'에 반입한 물품의 반출통고만 '보세구역운영인'이 화주등에게 하고, ② 보세판매장·보세구역외장치장·자가용보세창고·보세공장에 반입한 물품의 반출통고는 모두 '관할세관장'이 화주등에게 한다. 따라서 운영인 주체인 영업용보세창고가 '주체가 다른 하나'로 정답이다. [오답 ②③④⑤] 보세판매장·보세구역외장치장·자가용보세창고·보세공장은 모두 관할세관장이 반출통고하는 보세구역으로 주체가 동일하다(영업용보세창고를 제외한 나머지 특허보세구역 및 보세구역외장치장은 관할세관장 주체). ※ 보조 근거: 지정장치장·세관지정 보세창고는 '화물관리인'이 통고한다. 본 항목의 핵심은 '특허보세구역 중 영업용보세창고만 운영인, 그 외(자가용·보세공장·보세건설장·보세전시장·보세판매장)와 보세구역외장치장은 관할세관장'이라는 매핑이며, 이는 본 프로젝트의 2020 no.3·2022 no.25·2023 no.20·2025 no.24 출제와도 일치한다.",
