        "보세운송 신고·승인신청을 '할 수 있는 자'(보세운송업자·화주·관세사)와 '승인대상 물품'을 혼동하지 말 것 — 화물운송주선업자·보세구역 운영인은 신고·승인신청 주체가 아님(2024 no.13)",
        "'화주 또는 화물에 대한 권리를 가진 자가 직접 보세운송하는 물품'은 회차에 따라 분류가 갈린다 — 2023 no.24 정답키는 이를 '승인대상'으로 보았다. 신고대상의 고정 예시로 외우지 말고 출제 회차 정답키 기준으로 판단할 것"
