      "conceptExplanation": "보세구역외장치(법 제156조)는 외국물품을 원칙적 장치장소인 보세구역이 아닌 곳에 예외적으로 장치하도록 세관장이 허가하는 제도다. 시험에서는 ①허가(신고 아님) ②허가대상 ③허가기간 ④연장사유 ⑤허가수수료 ⑥담보 6개 축이 반복 출제된다.\n\n[1] 허가 vs 신고 — 보세구역외장치는 '세관장의 허가'를 받아야 한다(신고 X). 교통이 불편한 지역에 양륙되어 보세구역 운반이 불합리한 물품도 '신고'가 아니라 '허가' 대상이다(2024-19①, 2023-15 함정).\n\n[2] 허가대상(보세화물관리고시) — 크기·무게 과다로 창고 안 장치 곤란 물품, 다량의 산물로서 보세구역 장치 후 재운송이 불합리한 물품, 부패·변질 우려(또는 다른 물품 오손 우려)·방진·방습 등 특수보관 필요 물품, 귀중품·의약품·살아있는 동·식물 등 보세구역 장치 곤란 물품 등. ※ '수출신고가 수리된 물품'은 허가대상이 아니다(2025-18⑤ 정답).\n\n[3] 허가기간 — 6개월의 범위 내에서 세관장이 필요하다고 인정하는 기간으로 정한다. '1년'·'3년'·'30일'은 모두 함정(2020-19②, 2021-1①, 2023-19②).\n\n[4] 연장사유(보세화물관리고시) — ①해당 화물을 반입할(동일세관 관할구역 내) 보세구역이 없는 경우 ②품목분류 사전심사 지연으로 수입신고할 수 없는 경우 ③법 제226조에 따른 수입요건·선적서류 등 신고(수리)요건 미구비 ④인지부서의 자체조사·고발의뢰, 공매·경매낙찰·몰수확정·국고귀속 등 결정에 따른 조치 ⑤재해 등 부득이한 사유로 생산지연·반송대기 등 세관장 인정 사유. ※ 연장 절차는 '보세구역외장치기간연장(신청)서'를 제출해 세관장의 '승인'을 받는다(2024-19③ 정답). ※ '국내판로 미결정'은 연장사유가 아니다(2021-8② 정답).\n\n[5] 허가수수료 — 허가건수 단위로 징수하되, 동일 선박(모선)·항공기로 수입된 '동일 화주'의 화물을 '동일 장소'에 반입하는 때에는 1건의 허가수수료로 징수(허가)할 수 있다. ※ 화주가 다르면 동일 장소라도 1건으로 묶을 수 없다(2024-19④ 함정, 2023-15② 정답). ※ 협정에 의해 관세가 면제되는 물품은 장치허가수수료를 면제한다(2023-15③ 함정).\n\n[6] 담보 — 담보액은 수입통관 시 실제 납부하여야 할 관세 등 제세 상당액으로 한다('120%'·'110%'는 함정, 2024-19⑤, 2021-1⑤). 세관장은 허가신청을 받으면 '허가기간에 1개월을 가산한 기간'을 담보기간으로 하여 담보제공을 명할 수 있다(2017류·2024-17B, 2022-15①). 제조업체 수출용원자재(농·축·수산물 제외)·무세물품·정부용품·방위산업용물품 등은 담보생략 대상이나, '재수출 면세 예정물품'은 보세구역외장치 담보생략 기준에 없다(2020-20③ 정답).",
      "trapAnalysis": "이 유형은 '맞는 것/틀린 것' 발문을 바꿔가며 같은 함정을 돌려 쓴다. 핵심 함정 패턴:\n\n(1) 허가↔신고 바꿔치기 — 보세구역외장치는 '허가'인데 선지에서 '신고'로 적는다(본문 ①). 교통 불편 지역·운반 불합리 물품도 '허가' 대상임을 잊으면 ①을 맞는 것으로 오인.\n\n(2) 허가기간 숫자 바꾸기 — 정답은 '6개월'. 선지에서 '1년'(2020-19, 2021-1) 또는 '3년'(본문 ②)으로 부풀린다. 보세건설장·정부비축·LME 등 다른 장치기간과 섞어 혼동 유발.\n\n(3) 수수료 1건 합산요건 빼먹기 — 1건 합산은 '동일 선박+동일 화주+동일 장소' 3요건 모두 충족 시만 가능. 선지는 '화주가 다르더라도'(본문 ④)로 화주 요건을 빼서 오답을 만든다.\n\n(4) 담보액에 %를 붙이기 — 정답은 '관세 등 제세 상당액'(100%). 선지는 '120%'(본문 ⑤) 또는 '110%'(2021-1)로 붙인다. 담보'기간'은 '허가기간+1개월'이라는 별개 숫자와도 혼동시킨다.\n\n(5) 연장사유 오답 끼우기 — '국내판로 미결정'(2021-8), '허가신청 업체 구역 내 반입장소 없음'(2019-1, 이는 연장이 아닌 애초 신청사유)을 연장사유처럼 제시. 본 정답 ③(연장은 연장신청서 제출→세관장 승인)은 절차 자체를 정확히 서술한 유일한 옳은 선지다.",
      "answerKey": "정답 ③. 보세구역외장치 허가기간을 연장하려는 자는 '보세구역외장치기간연장(신청)서'를 제출하여 세관장으로부터 '승인'을 받아야 한다 — 절차가 정확하므로 맞는 설명.\n\n오답: ①은 '신고'가 아니라 세관장의 '허가' 대상이므로 틀림. ②는 허가기간이 '3년'이 아니라 '6개월의 범위 내'이므로 틀림. ④는 동일 장소에 반입되어도 '화주가 다르면' 1건으로 묶어 허가할 수 없으므로(동일 선박+동일 화주+동일 장소 3요건 필요) 틀림. ⑤는 담보액이 관세 상당액의 '120%'가 아니라 '수입통관 시 실제 납부할 관세 등 제세 상당액(100%)'이므로 틀림.",
