        "통관을 위한 개장·분할구분·합병 작업도 보수작업 승인 대상이다(2023 no.18 ⑤는 '승인 불요'로 적어 틀림).",
        "HSK 10단위 변화는 원칙 불가이나, 부패·변질 우려 등 세관장이 타당하다고 인정하면 예외 인정(2024 정답). '기능개선으로 HSK 변화 = 무조건 보수작업'은 틀림(2025 함정).",
