      "lawBasis": "관세법 제158조(보수작업) — 보세구역 장치물품의 보수작업 시 세관장 승인(제2항), 승인신청일부터 10일 이내 승인 여부 통지(제3항), 기간 내 미통지 시 그 기간이 끝난 날의 다음 날에 승인한 것으로 간주(제4항, 묵시적 승인), 외국물품에 부가된 내국물품은 외국물품으로 봄(제5항), 외국물품은 수입될 물품의 보수작업 재료로 사용 불가(제6항). 보세화물관리에 관한 고시(보수작업 포괄승인 1년·완료보고·보세구역 외 작업·HSK 변화 예외 인정 등 세부 절차). 관세법 제160조(잔존물 관세 징수)와 연계.",
