      "conceptExplanation": "보세구역(및 보세운송 중) 장치물품의 「폐기·멸실」은 화물관리(3과목)에서 매년 반복 출제되는 최빈출 핵심 주제로, 관세징수 여부·비용부담 주체·잔존물 과세·미이행 시 행정대집행이라는 4개 축으로 정리해야 한다.\n\n[1] 관세 징수 여부(관세법 §160·§161)\n- 「징수하지 않는 경우」: ①재해 그 밖에 부득이한 사유로 멸실된 때, ②미리 세관장의 승인을 받아 폐기한 때. 이 두 경우는 관세를 징수하지 아니한다.\n- 「즉시 징수하는 경우」: ①보세구역 장치물품이 도난 또는 분실된 때, ②세관장 승인 없이 임의 폐기한 때. 이때는 운영인·보관인(지정보세구역은 화물관리인)으로부터 관세를 즉시 징수한다.\n- 즉 \"멸실·승인폐기 = 징수 안 함 / 도난·분실·무단폐기 = 즉시 징수\"가 대원칙이다.\n\n[2] 자기비용 폐기·반송 및 비용부담\n- 부패·손상 등으로 장치물품을 폐기하려는 자는 세관장의 「승인」을 받아야 한다(허가 아님).\n- 세관장의 폐기 또는 반송 「명령」을 받은 화주·반입자 또는 그 위임을 받은 자는 그 물품을 「자기비용」으로 폐기 또는 반송하여야 한다.\n\n[3] 잔존물 과세\n- 폐기 후 잔존물이 있는 경우에는 그 잔존물의 「성질과 수량」에 따라 관세 등 각종 세금을 부과한다(폐기 전 또는 반입 당시 상태가 아니라 '잔존물' 상태 기준).\n\n[4] 행정대집행·비용징수\n- 폐기명령을 받은 자가 기간이 경과하여도 폐기·반송하지 않은 물품 중 방치 시 공익을 해할 것으로 인정되는 물품은 세관장이 「행정대집행법」에 따라 대집행할 수 있다.\n- 세관장은 예산 편성 시 폐기처분 대집행에 소요되는 연간 예상비용을 예산에 계상하여야 한다.\n- 행정대집행법에 따라 비용납부명령서를 받은 자가 납기 내 납부하지 않으면 「국세징수법에 따른 체납처분의 예」에 따라 징수한다(행정절차법이 아님).\n- 폐기명령 대상물품의 공시송달은 공고한 날부터 7일을 경과함으로써 효력이 발생한다.\n- 화주 등이 불분명하고 폐기가 급박한 경우라도 세관장은 「공고 후」 폐기할 수 있으며, '별도 공고 없이' 폐기한다는 표현은 함정이다.\n\n보세운송 중 물품의 폐기·멸실도 동일 법리가 적용된다: 폐기는 세관장 승인 필요(신고만으로 불가), 승인폐기는 관세 징수 안 함, 잔존물은 잔존물에 대해 관세 징수, 멸실신고서는 도착지가 아니라 「발송지(보세운송신고지)」 세관장에게 제출한다.",
      "trapAnalysis": "이 유형의 핵심 함정은 '비슷하지만 반대이거나 근거가 다른 표현'으로 정·오답을 가르는 데 있다.\n\n1) 징수/비징수 뒤집기(2019 no.8): \"재해 등 부득이한 사유로 멸실된 때와 세관장 승인을 얻어 폐기한 때 관세를 즉시 징수한다\"는 정반대 함정. 멸실·승인폐기는 징수하지 '않는' 사유다. 반대로 도난·분실은 즉시 징수한다는 점을 같은 보기에 섞어 헷갈리게 만든다.\n\n2) 미이행 시 징수 근거법령 바꿔치기(2020 no.23·본 대표문항): 행정대집행 비용 미납 시 징수 근거를 '행정절차법'으로 적으면 오답. 정답 근거는 「국세징수법에 따른 체납처분의 예」다. 법령명을 그럴듯한 다른 법으로 바꾸는 전형적 함정.\n\n3) '별도 공고 없이 폐기' 함정(2022 no.23): 화주 등이 불분명하고 폐기가 급박해도 세관장은 '공고 후' 폐기할 수 있다. '별도 공고 없이 폐기한다'고 단정하면 틀림.\n\n4) 잔존물 과세 기준 시점 함정(2023 no.21·2025 no.15): 폐기 후 잔존물은 '잔존물의 성질과 수량'에 따라 과세. '보세구역 반입 당시의 성질과 수량'으로 적으면 오답. 또 \"승인 여부와 관계없이 즉시 관세를 징수한다\"도 함정(승인폐기는 징수 안 함).\n\n5) 승인 vs 허가, 신고 vs 승인 혼동(2025 no.15): 장치물품 폐기는 '승인' 대상이다(허가·단순신고 아님). 보세운송 중 폐기도 '미리 세관장에게 신고 후 폐기'가 아니라 '승인'을 받아야 한다.\n\n6) 멸실신고서 제출처 함정(2025 no.15): 보세운송 중 멸실 시 멸실신고서는 '도착지' 세관장이 아니라 '발송지' 세관장에게 제출한다.",
      "answerKey": "정답은 ⑤. 행정대집행법에 따라 비용납부명령서를 받은 자가 납기 내에 납부하지 아니하면 「국세징수법에 따른 체납처분의 예」에 따라 징수하는 것이지 '행정절차법에 따라 징수'하는 것이 아니다. 행정절차법은 처분 절차를 규율하는 법이지 비용 징수의 근거가 아니므로 근거 법령을 잘못 든 ⑤가 틀린 설명이다.\n\n[오답인 이유]\n① 옳음 — 폐기·반송 명령을 받은 화주·반입자 또는 그 위임을 받은 자는 자기비용으로 폐기 또는 반송하여야 한다(비용은 명령을 받은 자 부담).\n② 옳음 — 폐기명령 대상물품에 대한 공시송달은 공고한 날부터 7일을 경과함으로써 효력이 발생한다.\n③ 옳음 — 폐기처분은 소각(열에너지화 작업 등 포함) 또는 매몰 등의 방법으로 처리한다.\n④ 옳음 — 세관장은 예산 편성 시 폐기처분 대집행에 소요되는 연간 예상비용을 예산에 계상하여야 한다.",
