        "과세가격 산정 기초는 '최초예정가격'이지 체감 후 '최종예정가격'이 아니다.",
        "매각처분 보류신청 시기는 '매각(공매) 전까지'이지 '낙찰 후 반출 전까지'가 아니다.",
        "매각된 물품의 질권자·유치권자는 다른 법령에도 불구하고 매수인에게 인도하여야 한다(인도 거부 불가). 2021 no.12·2024 no.25 단골 함정.",
