      "lawBasis": "관세법 제222조(보세운송업자등의 등록 및 보고)·제223조(보세운송업자등의 등록요건)·제224조(등록의 효력상실)·제175조(운영인의 결격사유), 관세법 시행령 제231조, 「화물운송주선업자에 관한 고시」(등록요건·등록기간 3년·변동신고 60일·행정제재·청문), 「물류정책기본법」 제43조(국제물류주선업의 등록)",
