      "lawBasis": "관세법 제222조(보세운송업자등의 등록 및 보고)·제223조(보세운송업자등의 등록요건)·제223조의2·제224조(등록의 효력상실), 관세법 시행령 제231조, 「보세운송에 관한 고시」(보세운송업자 등록·간이보세운송업자 지정·특정물품간이보세운송업자 지정요건·서류보관 등)",
      "sourceRef": "kinz.kr 보세사 기출 / 보세사 자격시험 제3과목 화물관리 — 2019 19번, 2020 19·22번, 2021 7·21번, 2022 11·12·14번, 2024 10·12번, 2025 12·13·14번 (bosesa-data-3-{연도}.js)"
