      "lawBasis": "관세법 제157조(물품의 반입·반출), 제157조의2(수입신고수리물품의 반출), 제213조(보세운송의 신고)·제215조(보세운송 보고); 「보세화물관리에 관한 고시」(반입신고·반출신고·반출입대장 기록, 동일사업장 내 보세구역 간 이동의 보세운송신고 갈음); 「보세화물 입출항 하선 하기 및 적재에 관한 고시」(하선장소 반입신고 단위 House/Master B/L, 차상반출 시 반출입신고 생략)",
      "sourceRef": "보세사 자격시험 3과목(화물관리) 기출: 2021 no.2(대표문항)·no.15·no.23 / 2022 no.15·no.16 / 2023 no.12·no.13 / 2024 no.16 / 2025 no.6·no.17. 파일: C:\\Users\\pkm77\\Desktop\\home-desktop project\\project-dashboard\\claude\\previews\\tradelogix-nexus\\bosesa-data-3-2021.js, bosesa-data-3-2022.js, bosesa-data-3-2023.js, bosesa-data-3-2024.js, bosesa-data-3-2025.js"
