      "lawBasis": "「보세화물 입출항·하선·하기 및 적재에 관한 고시」(하선신고·하선장소 물품반입 관련 조항). 근거법: 관세법 제140조(물품의 하역), 제157조(물품의 반입·반출). 하선장소 반입기한·반입신고 단위(House/Master B/L)·반입기간 연장승인·공컨테이너 미반입 보고는 동 고시에 규정.",
      "sourceRef": "보세사 기출 제3과목(화물관리) — 2021년도 no.15(대표문항), 2020년도 no.9·no.16, 2023년도 no.5, 2024년도 no.2. bosesa-data-3-2020.js / -2021.js / -2023.js / -2024.js (TradeLogix Nexus 대시보드). 정답: 2021 no.15=④, 2020 no.9=③, 2020 no.16=①, 2023 no.5=①, 2024 no.2=④."
