        "내국환적운송(국내 국제항 간 외국무역선) 대상 4종: ①환적화물 ②수출화물(수출신고 수리) ③내국물품인 공컨테이너 ④최초 입항지에서 B/L·AWB상 최종 목적지로 운송하려는 수입 외국물품",
