      "lawBasis": "「환적화물 처리절차에 관한 특례고시」 제12조(비가공증명서 발급) — 본 문제의 직접 근거. 세관장이 보세구역에 일시장치된 환적화물에 대해 발급(제1항), 신청 시 보세구역운영인 또는 자유무역지역 입주기업체가 발행한 「일시장치확인서」와 비가공증명 신청서 제출(제2항, 선박 간 직접 환적 시 일시장치확인서 제출 생략 가능), 세관장은 제1항 충족 여부와 관세법 시행규칙 제76조의 직접운송원칙을 준용해 심사하고 필요 시 관계서류 요구·물품검사 가능(제3항). 일시장치확인서의 기재사항(일시장치장소·화물관리번호·B/L(AWB)번호·품명/반입중량/수량·반입일자·비가공 사실 확인)은 동 고시 별지 서식에 규정. 보충 근거로 비가공·보존행위의 개념을 뒷받침하는 관세법 제141조(외국물품의 일시양륙 등)·제158조(보수작업)와, FTA 특혜관세 적용 시 요구되는 직접운송원칙(관세법 시행규칙 제76조 및 「자유무역협정의 이행을 위한 관세법의 특례에 관한 법률」)을 참고. ※ '관세법 제232조의2'는 본 문제의 직접 근거가 아니므로 인용에서 제외(원산지증명서 일반은 제232조, 제232조의2는 발급비용 지원 조항).",
