      "lawBasis": "「보세화물장치기간 및 체화관리에 관한 고시」 국고귀속(체화처리) 관련 규정(국고귀속 보류 대상 물품 조항, 통상 제38조). 동 조항은 ①관세법 위반 조사 중인 물품 ②국가기관·지방자치단체·공기업·준정부기관·그 밖의 공공기관이 '수입하는' 물품으로서 국고귀속 보류요청이 있는 물품 ③부패·손상·실용시효 경과 등으로 국고귀속 실익이 없는 물품 ④특수용도에만 한정되어 국고귀속 후에도 공매낙찰 가능성이 '없는' 물품 ⑤이의신청·심판청구·소송 등 쟁송이 제기된 물품 ⑥국고귀속 시 인력·예산 부담으로 국고손실이 야기되는 물품 등을 보류 대상으로 정한다. 상위 근거: 관세법 제210조(매각방법)·제212조(국고귀속).",
