      "question": "보세화물의 장치장소 결정을 위한 화물분류 기준으로 틀린 것은?",
      "choices": [
        "화주 또는 그 위임을 받은 자가 장치장소에 대한 별도의 의사표시가 없는 경우 House B/L화물은 보세구역운영인이 선량한 관리자로서 장치장소를 결정한다.",
        "선사는 화주 또는 그 위임을 받은 자가 운영인과 협의하여 정하는 장소에 보세화물을 장치하는 것을 원칙으로 한다.",
        "화주 또는 그 위임을 받은 자가 장치장소에 대한 별도의 의사표시가 없는 경우 Master B/L화물은 선사가 선량한 관리자로서 장치장소를 결정한다.",
        "보세창고, 보세공장, 보세판매장에 반입할 물품은 특허시 세관장이 지정한 장치물품의 범위에 해당하는 물품만 해당 보세구역에 장치한다.",
        "입항전 또는 하선(기)전에 수입신고가 되거나 보세운송신고가 된 물품은 보세구역에 반입함이 없이 부두 또는 공항내에서 보세운송 또는 통관절차와 검사절차를 수행하도록 하여야 한다."
      ],
