      "conceptExplanation": "입항 전 또는 하선(기) 전에 수입신고나 보세운송신고를 하지 않은 보세화물은 「보세화물관리에 관한 고시」의 '화물분류기준'에 따라 장치장소를 정한다. 핵심은 '누가(어떤 주체가)' 선량한 관리자로서 장치장소를 결정하는가이다. ①대원칙: 선사는 화주(또는 그 위임을 받은 자)가 '운영인과 협의'하여 정하는 장소에 보세화물을 장치하는 것을 원칙으로 한다(세관장과 협의가 아님). ②화주의 별도 의사표시가 없는 경우의 결정주체 — Master B/L 화물은 '선사'가 선량한 관리자로서 장치장소를 결정하고, House B/L 화물은 '화물운송주선업자(포워더)'가 선량한 관리자로서 '선사 및 보세구역운영인과 협의'하여 장치장소를 결정한다. 즉 결정주체는 B/L 종류에 따라 Master=선사, House=포워더로 갈린다. ③포워더가 선량한 관리자의 의무를 다하지 못할 경우에는 세관지정장치장 또는 세관지정 보세창고를 장치장소로 한다. ④특수물품: 위험물·보온보냉물품·검역대상물품 등은 그 물품을 장치하기에 적합한 요건(조건)을 갖춘 보세구역에 장치한다(위험물은 검사대상화물로 선별되더라도 세관지정장치장이 아니라 위험물 장치요건을 갖춘 보세구역에 장치). ⑤특허보세구역(보세창고·보세공장·보세전시장·보세판매장)에는 특허 시 세관장이 지정한 장치물품 범위에 해당하는 물품만 장치한다. ⑥입항 전·하선(기) 전에 수입신고 또는 보세운송신고가 된 물품은 보세구역에 반입함이 없이 부두 또는 공항 내에서 보세운송·통관·검사 절차를 수행하도록 한다.",
      "trapAnalysis": "함정의 핵심은 House B/L 화물의 장치장소 '결정주체'를 바꿔치기하는 것이다. 정답 선지 ①은 결정주체를 '보세구역운영인'으로 적어 놓았으나, 화주의 별도 의사표시가 없는 House B/L 화물의 결정주체는 '화물운송주선업자(포워더)'이며, 포워더가 '선사 및 보세구역운영인과 협의'하여 결정한다 — 즉 보세구역운영인은 '협의 상대방'일 뿐 단독 결정주체가 아니다. 출제자는 협의 상대방(운영인)을 결정주체로 슬쩍 끌어올려 오답을 만든다. 같은 유형이 연도마다 결정주체를 ⓐ세관장(2019 no.21 정답 선지), ⓑ보세구역운영인(2021 no.25 정답 선지)으로 번갈아 바꿔 출제된다. 반대로 2022 no.17은 'House B/L=화물운송주선업자가 선사·운영인과 협의'를 맞는 선지로 제시해 정답으로 삼았으니, '틀린 것'을 고르는지 '맞는 것'을 고르는지 발문 방향을 먼저 확인해야 한다. 또 다른 단골 함정은 ②의 '운영인과 협의'를 '세관장과 협의'로 바꾸는 것(2022 no.17 ①번 오답)과, Master B/L 화물의 결정주체를 '화물운송주선업자'로 바꾸는 것(2022 no.17 ②번 오답)이다.",
      "answerKey": "정답은 ①. House B/L 화물의 장치장소를 화주의 별도 의사표시가 없을 때 '보세구역운영인'이 결정한다고 한 부분이 틀리다 — 실제로는 '화물운송주선업자(포워더)'가 선량한 관리자로서 선사 및 보세구역운영인과 협의하여 결정한다. ② 선사는 화주(위임받은 자)가 운영인과 협의하여 정하는 장소에 장치하는 것이 원칙이므로 맞다. ③ Master B/L 화물은 별도 의사표시가 없으면 선사가 선량한 관리자로서 결정하므로 맞다. ④ 특허보세구역에는 특허 시 지정된 장치물품 범위 내 물품만 장치하므로 맞다. ⑤ 입항 전·하선(기) 전 수입신고 또는 보세운송신고가 된 물품은 보세구역 반입 없이 부두·공항 내에서 보세운송·통관·검사를 수행하도록 하므로 맞다.",
