        "발문 방향 주의: 2019 no.21·2021 no.25·2024 no.24는 모두 '틀린 것'을 고르는 문제이고, 2022 no.17만 '맞는 것'을 고르는 문제다. 묻는 방향을 먼저 표시하고 풀 것 — 특히 2022는 정답이 '맞는 선지'(House B/L=포워더가 선사·운영인과 협의)임에 유의.",
