      "question": "( ) 안에 들어갈 내용을 바르게 나열한 것은?\n\n관세법 제157조의2에 따라 관세청장이 정하는 보세구역에 반입된 물품의 화주 또는 반입자는 관세법 제177조에도 불구하고 그 물품의 ( A )로부터 ( B ) 이내에 해당물품을 보세구역으로부터 반출하여야 한다. 세관장은 화주 또는 반입자가 이를 위반한 경우에는 관세법 제277조에 따라 100만원 이하의 ( C )을(를) 부과한다.",
