      "question": "항공입항화물 적하목록 제출에 관한 설명이다. ( ) 안에 들어갈 내용을 바르게 나열한 것은?\n\n적하목록 제출의무자는 항공기가 입항하기 ( A )까지 적하목록을 항공기 입항예정지 세관장에게 전자문서로 제출해야 한다. 다만, 근거리 지역의 경우에는 적재항에서 항공기가 ( B )까지, 특송화물의 경우에는 항공기가 입항하기 ( C )까지 제출해야 한다.",
