      "question": "적하목록 정정신청 기간과 관련하여 ( )안에 들어갈 내용으로 맞는 것은?\n\n① 하선(기)결과 이상보고서 및 반입결과 이상보고서가 제출된 물품은 보고서 제출일로부터 ( )일 이내\n② 수입화물의 적하목록을 정정신청하려는 경우는 선박(항공기) 입항일로부터 ( )일 이내\n③ 수출화물의 적하목록을 정정신청하려는 경우 해당 수출물품을 적재한 선박, 항공기가 출항한 날로부터 해상화물은 ( )일 이내, 항공화물은 ( )일 이내",
