      "lawBasis": "「보세화물 입출항 하선 하기 및 적재에 관한 고시」 적하목록(적재화물목록) 정정신청 규정 — 이상보고서 제출물품 15일, 수입(입항)화물 입항일부터 60일, 수출(출항)화물 출항일부터 해상화물 90일·항공화물 60일. (관세법 제135조·제136조 입출항절차 및 동 고시 정정·생략 조항)",
      "sourceRef": "보세사 기출 제3과목(화물관리): 2020년 18번, 2021년 17번, 2023년 3번, 2025년 5번 (TradeLogix Nexus bosesa-data-3-2020/2021/2023/2025.js). 대표문항은 2020년 18번(세 기간 전부 포함, 정답 ⑤)."
