      "lawBasis": "관세법 제135조(입항절차)·제136조(출항절차)·제157조(물품의 반입·반출), 「보세화물 입출항 하선 하기 및 적재에 관한 고시」 적하목록 정정신청·정정신청 생략·직권정정 관련 규정(적하목록 정정신청 기한 및 생략범위 조항, 하기결과 이상물품 적용특례 조항)",
