      "conceptExplanation": "관세법 제241조 제3항·제4항은 보세구역에 반입한 물품을 일정기간 안에 통관하도록 강제하기 위해 「신고지연 가산세」 제도를 둔다.\n\n(1) 부과요건 — 관세청장이 정하는 보세구역(통상 부두 내 지정장치장·보세창고)에 반입한 물품을 반입일부터 「30일 이내」에 수입 또는 반송 신고를 하지 않으면 가산세가 부과된다. 반입 후 신고를 미루는 「체화(滯貨)」를 방지하기 위한 제재다.\n\n(2) 요율 — 경과기간이 길수록 가산세율이 높아지는 「차등(누진) 요율」 구조다. 신고기한(반입일부터 30일)이 경과한 날부터 초과기간에 따라 과세가격의 1천분의 5 → 1천분의 10 → 1천분의 15 → 1천분의 20까지 단계적으로 올라간다. 즉 「최저율 1천분의 5, 최고율 1천분의 20」이다. 단순히 \"경과기간과 무관하게 일률 1천분의 5\"가 아니다.\n\n(3) 한도(상한) — 최고율이 적용되더라도 가산세액은 「500만원」을 초과할 수 없다(상한선).\n\n(4) 면제(비징수) 대상 — 신고지연 가산세를 징수하지 않는 대표적 물품으로 ①수출용원재료(신용장 등 관련 서류로 수출용원재료임이 확인되는 경우에 한함) ②환적화물 ③여행자 휴대품 등이 있다. 반면 국가·지방자치단체가 직접 수입하는 물품이라도 한국전력공사처럼 「공기업이 직접 수입하여 사용할 물품」은 면제대상이 아니라 가산세 징수 대상이다.\n\n요약하면 \"30일 기준 → 1천분의 5~20 차등요율 → 500만원 한도 → 수출용원재료·환적화물·여행자휴대품 면제\"가 핵심 골격이다.",
      "trapAnalysis": "이 유형의 단골 함정은 「숫자 바꿔치기」와 「면제대상 끼워넣기」다.\n\n①번처럼 차등요율이라는 큰 틀은 맞게 써놓고 최고율을 '1천분의 15'로 슬쩍 낮추는 함정 — 실제 최고율은 1천분의 20이다. 차등 자체를 부정하고 \"경과기간과 무관하게 1천분의 5\"라고 단정하는 변형(2023 no.16의 한 선지)도 같은 함정으로, 차등(누진)이라는 점을 잊으면 걸린다.\n\n②번처럼 한도액(500만원)을 정확히 제시하면 정답이지만, 다른 선지에서는 '1,000만원' 같은 틀린 한도를 던져 혼동을 유발한다(2023 no.16).\n\n③번은 면제대상을 나열하면서 진짜 면제대상(환적화물·여행자휴대품)에 가짜(수출용원재료가 아닌 다른 물품)를 섞거나, 거꾸로 수출용원재료를 「징수 대상」으로 둔갑시킨다. 특히 한국전력공사 등 공기업 직수입 사용물품을 \"면제\"라고 하면 함정 — 이는 오히려 징수 대상이다(2023 no.16 정답).\n\n④번은 대상 보세구역을 '부두 내'로 한정하는 규정을, '부두 내와 부두 밖'을 모두 포함시켜 범위를 부풀리는 함정이다.\n\n⑤번은 가산세가 아닌 「장치기간」 논점을 끼워 넣어 출제 — 보세구역 간 이동물품의 장치기간은 종전 보세구역 기간을 합산하는데, '현 보세구역만'이라고 해 틀리게 만든다.",
      "answerKey": "정답 ②",
