        "한도액을 '1,000만원'으로 키워 쓴 함정과 혼동 금지 — 정답 한도는 500만원이다.",
        "면제대상(환적화물·여행자휴대품·수출용원재료)과 징수대상(공기업 직수입 사용물품, 예: 한국전력공사)을 거꾸로 묻는 점에 유의.",
