      "lawBasis": "관세법 제241조(수출·수입 또는 반송의 신고) 제3항·제4항 및 동법 시행령 제247조(가산세) — 보세구역 반입일부터 30일 이내 미신고 시 경과기간에 따라 과세가격의 1천분의 5~1천분의 20 차등 가산세, 가산세액은 500만원 한도(시행령 제247조 제1항·제3항). 면제대상은 동법 시행령 제247조 제4항 및 관련 고시상 수출용원재료(신용장 등으로 확인되는 경우)·환적화물·여행자 휴대품 등이다.",
      "sourceRef": "보세사 기출 제3과목 화물관리 — 2019년 23번(대표문항, 정답 ②), 2021년 22번(신고지연 가산세·장치기간, 정답 ③), 2023년 16번(수입·반송 신고지연 가산세, 정답 ④). 파일: bosesa-data-3-2019.js / bosesa-data-3-2021.js / bosesa-data-3-2023.js (TradeLogix Nexus 대시보드)"
