        "LCL화물 중 컨테이너에서 적출하지 아니한 상태로 보세운송하는 경우 House B/L 단위로 신고해야 한다.",
        "보세운송신고를 한 자는 보세구역 출발 이후 차량고장 등으로 운송수단이 변경되는 경우 해당 사정이 발생한 때로부터 다음날까지 다시 배차예정내역을 신고해야 한다."
