        "경유지 작업제한: 보세운송 중 외국물품은 경유지에서 개장·분리·합병·적출·해체 등 동일성 훼손 작업 임의 불가(2019-20 ④). 컨테이너 개장이 필요하면 최초 도착지 보세구역 운영인(보세사 포함) 확인을 받아 개장(2020-1 ③).",
