      "conceptExplanation": "해상입항화물의 「하선(下船)」 절차는 ① 하선신고 → ② 하선장소 지정·반입 → ③ 하선결과보고의 3단계로 이루어진다(「보세화물 입출항 하선 하기 및 적재에 관한 고시」).\n\n[1] 하선신고: 화물을 하선하려는 자(선사 등)는 「Master B/L 단위」의 적재화물목록을 기준으로 하선신고서를 세관장에게 「전자문서」로 제출하는 것이 원칙이다. 다만 검역 등을 위해 분할하선해야 하는 등 부득이한 경우에는 서류로 하선신고할 수 있으며, 이 경우 하선작업 완료 후 다음 날까지 하선신고서(결과)를 전자문서로 제출한다.\n\n[2] 하선장소 지정: 하선장소란 「선박으로부터 하역된 화물을 반입할 수 있는 보세구역」을 말하며, 항만의 경우 보세구역이 아닌 부두를 포함한다. 입항전수입신고 또는 하선전보세운송신고가 된 물품으로서 검사가 필요하다고 인정되는 물품은 「세관장이 지정하는 장소」에 하선한다(선사가 지정하는 장소가 아님). 하선장소 변경은 「반입 전」에 변경신청서를 제출해 승인받아야 한다(반입 후 변경 불가).\n\n[3] 하선장소 반입기한: 하선신고를 한 자는 ▲컨테이너화물은 입항일로부터 「3일 이내」(고시 개정으로 현행 5일·종전 3일), ▲원목·곡물·원유 등 산물(벌크)은 입항일로부터 「10일 이내」에 하선장소에 반입해야 한다.\n\n[4] 하선결과보고: 하선결과 물품이 적재화물목록과 「상이할 때」에는 하선작업 완료 후 「다음 날까지」 하선결과보고서를 세관장에게 제출해야 한다.",
      "trapAnalysis": "출제자는 단위·기준일·기한 숫자를 미세하게 바꿔 함정을 만든다. ① 하선신고서의 기준 단위를 'Master B/L'에서 'House B/L'로 바꿔치기(단위 함정). ② 하선결과보고서 제출시한을 '완료 후 다음 날까지'가 아니라 '완료한 날까지'로 하루 당겨 제시(기한 1일 차이 함정). ④ 하선장소 변경은 '반입 전'에 승인받아야 하는데 '반입 후'로 시점을 뒤집음(시점 역전 함정). ⑤ 컨테이너화물 반입기한(3일)에 산물 기한(10일)을 끼워 넣어 숫자를 교차시킴(품목별 기한 교차 함정). 2023년 4번에서는 거꾸로 '검사 필요 물품을 선사가 지정하는 장소에 하선'으로 지정권자를 선사↔세관장으로 바꾼 함정이 출제됐다.",
      "answerKey": "정답은 ③. 하선결과 물품이 적재화물목록과 상이할 때 하선작업 완료 후 다음 날까지 하선결과보고서를 세관장에게 제출한다는 것은 고시 규정 그대로다. ①은 하선신고 기준 단위가 House B/L이 아니라 Master B/L이므로 오답. ②는 하선신고가 전자문서 제출 원칙이고 서류 제출은 부득이한 경우 예외이며 보기 내용이 고시와 부합하지 않아 오답. ④는 하선장소 변경은 '반입 후'가 아니라 '반입 전'에 변경신청서를 제출·승인받아야 하므로 오답. ⑤는 컨테이너화물 반입기한이 10일이 아니라 3일이고 10일은 산물(원목·곡물·원유)에 적용되는 기한이므로 오답.",
