      "lawBasis": "[1] 관세법 제140조(물품의 하역) — 입항절차(제135조)를 마친 후 하역·환적 원칙 및 세관장 허가 예외(제1항)와 10일 내 통지·허가의제(제2·3항), 하역 시 세관장 신고·현장확인(제4항), 세관장의 하역 장소·통로·기간 제한권(제5항), 국제무역선(기)에 내국물품·국내운항선(기)에 외국물품 교차적재 제한과 허가 예외(제6항). [2] 관세법 제141조(외국물품의 일시양륙 등) — 일시양륙, 운송수단 간 환적·물품 이동·사람 이동에 대한 세관장 신고·현장확인(정답 지문 ②의 직접 근거 조문) 및 간이신고·확인생략 특례. 관련: 관세법 시행령 제161조(물품의 하역 등의 허가신청), 「보세화물 입출항 하선·하기 및 적재에 관한 고시」.",
