        "보세구역외장치 '허가'(법156조, 세관장 허가 필요: 크기·무게 과다 등)와, 법155조 단서상 당연히 보세구역 외 장치가 가능한 물품(수출신고수리물품 등)을 혼동하지 말 것.",
