      "conceptExplanation": "관세법상 외국무역선·외국무역기(국제무역선·국제무역기)의 운항과 국제항(구 '개항') 출입 관련 핵심 절차를 묶은 유형이다. ① 운항 한정: 외국무역선·외국무역기는 국제항(개항)에 한정하여 운항할 수 있고, 대통령령으로 정하는 바에 따라 국제항이 아닌 지역에 출입허가를 받은 경우에만 예외적으로 그 지역을 운항할 수 있다. ② 출항허가: 외국무역선·외국무역기가 국제항을 출항하려면 선장·기장이 출항 전에 세관장의 출항허가를 받아야 한다(입항 시에는 입항보고). ③ 국제항이 아닌 지역 출입허가의 처리기한: 세관장은 국제항이 아닌 지역에 대한 출입허가 신청을 받은 날부터 '10일 이내'에 허가 여부를 신청인에게 통지하여야 하며, 그 기간(또는 연장된 처리기간) 내에 허가 여부 또는 처리기간 연장을 통지하지 아니하면 그 기간이 끝난 날의 다음 날에 허가를 한 것으로 본다. ④ 허가수수료: 국제항이 아닌 지역에 출입허가를 받으려는 선장·기장은 허가수수료를 납부하여야 한다. ⑤ 입출항 간소화: 입항절차를 마친 외국무역선이 다시 우리나라의 다른 국제항에 입항할 때에는 세관장이 서류제출 생략 등 간소한 절차로 입출항하게 할 수 있다. 이 유형은 '10일'이라는 통지기한 숫자를 '14일'·'7일' 등으로 바꿔 출제하는 것이 단골 함정이다. (현행법은 '개항'을 '국제항'으로 용어 변경하였으므로 같은 의미로 이해하면 된다.)",
      "trapAnalysis": "함정의 핵심은 ③의 '14일'이라는 기간 숫자다. 국제항(개항)이 아닌 지역 출입허가의 통지기한은 '10일 이내'가 정답인데, ③은 이를 '14일'로 부풀려 출제한 '기간 변조형' 함정이다. 보세사 시험에서는 적하목록 정정(15일·60일), 하선장소 반입(3일·10일) 등 다른 절차의 일수와 뒤섞어 '14일'·'7일'처럼 그럴듯한 숫자로 바꿔 오답을 유도한다. 나머지 선지(①운항 한정+허가 예외, ②다른 국제항 재입항 시 간소화, ④출항 전 출항허가, ⑤허가수수료 납부)는 모두 옳은 법문 그대로여서, 숫자 하나만 검증하면 풀리는 문항이다. 또한 '출항허가(④)'를 '출항보고'로, '입항절차(②)'를 '입항허가'로 바꿔 출제하는 변형도 주의해야 한다.",
      "answerKey": "정답은 ③. 국제항(구 '개항')이 아닌 지역에 대한 출입허가 신청을 받은 세관장은 신청을 받은 날부터 '10일 이내'에 허가 여부를 신청인에게 통지하여야 하는데(관세법 제134조 제2항·제3항), ③은 이를 '14일 이내'로 적어 기간을 잘못 표기했으므로 틀린 설명이다. ①은 국제항(개항) 한정 운항 원칙과 출입허가 예외를 정확히 서술해 옳고, ②는 입항절차를 마친 외국무역선의 다른 국제항(개항) 재입항 시 간소절차 적용이 가능하다는 점에서 옳으며, ④는 국제항(개항) 출항 시 선장·기장의 사전 출항허가 의무로 옳고, ⑤는 국제항이 아닌 지역 출입허가 시 허가수수료 납부 의무로 옳다. 따라서 '틀린 것'을 묻는 발문의 정답은 ③이다.",
      "cautions": [
        "통지기한 '10일'을 7일·14일·15일 등 다른 절차 일수와 혼동하지 말 것 — 국제항(개항) 아닌 지역 출입허가 통지기한은 10일 이내다.",
        "'입항'은 입항보고(절차), '출항'은 세관장의 출항허가가 필요하다 — 입출항의 허가/보고 대상이 뒤바뀐 선지에 주의.",
        "'국제항(개항)에 한정하여 운항'이 원칙이고 '국제항이 아닌 지역 출입허가'는 예외 — 원칙과 예외를 뒤집은 서술에 주의.",
        "현행 관세법은 '개항'을 '국제항'으로 용어를 바꿨다(2020. 12. 22. 개정) — 같은 개념이므로 용어가 달라도 동일하게 적용.",
        "처리기간(10일) 내 세관장이 허가 여부·처리기간 연장을 통지하지 않으면 처리기간 만료일 다음 날 허가를 한 것으로 본다는 간주규정도 함께 출제될 수 있다."
      ],
      "memorize": [
        "국제항(개항)이 아닌 지역 출입허가 통지기한 = 신청받은 날부터 10일 이내",
        "외국무역선·외국무역기 = 국제항(개항)에 한정 운항(예외: 국제항 아닌 지역 출입허가)",
        "국제항(개항) 출항 = 선장·기장이 출항 전 세관장 출항허가",
        "국제항 아닌 지역 출입허가 = 허가수수료 납부 의무",
        "처리기간(10일) 내 미통지 시 = 만료일 다음 날 허가 간주"
      ],
      "lawBasis": "관세법 제134조(국제항 등에의 출입): 제1항(외국무역선·외국무역기는 국제항에 한정하여 운항, 다만 대통령령으로 정하는 바에 따라 출입허가를 받은 경우 예외)·제2항(국제항이 아닌 지역 출입허가 신청을 받은 날부터 10일 이내 허가 여부 통지)·제3항(처리기간 내 허가 여부·처리기간 연장 미통지 시 그 기간이 끝난 날의 다음 날에 허가 간주)·허가수수료 규정, 제135조(입항절차—입항보고), 제136조(출항절차—출항허가). 국제항이 아닌 지역 출입허가 신청에 대한 세관장의 통지기한은 신청을 받은 날부터 '10일 이내'이다(2020. 12. 22. 개정으로 '개항'이 '국제항'으로 용어 변경). ※ 조문 항 번호는 개정 연혁에 따라 다소 다를 수 있으나 통지기한이 '10일 이내'라는 점은 동일하다.",
      "sourceRef": "2020년도 보세사 자격시험 제3과목 화물관리 문4 (출처 파일: bosesa-data-3-2020.js, 원자료 '20년 3과목.pdf')"
