      "lawBasis": "관세법 제157조(물품의 반입신고), 제157조의2(수입신고수리물품의 반출); 「수출통관 사무처리에 관한 고시」·「보세화물 입출항 하선 하기 및 적재에 관한 고시」 관련 조항(수출·반송신고수리물품 반입신고 및 갈음 규정)",
