        "부산항·인천항·인천공항·김해공항 항역 내 지정장치장 장치기간 = '2개월(60일)', 3개월 범위 연장 가능. 6개월 아님.",
        "장치기간 기산 원칙: 해당 보세구역 반입일 기준(원칙). 수차 반입·특허변경·보세운송 이전 시 각각의 예외 규정 적용."
