      "conceptExplanation": "관세법 제160조 제1항은 세관장이 보세구역에 장치된 물품에 대하여 화주·반입자에게 반송 또는 폐기를 명할 수 있는 대상물품을 열거하고 있다.\n\n[반송·폐기 명령 대상물품 — 법정 열거]\n① 사람의 생명이나 재산에 해를 끼칠 우려가 있는 물품\n② 부패되거나 변질된 물품 (※ '변질된 물품'이 대상. '변질될 우려가 있는 물품'은 아직 변질되지 않은 단계이므로 대상이 아님)\n③ 유효기간이 지난 물품\n④ 상품가치가 없어진 물품\n⑤ 위조상품, 모조품, 그 밖의 지식재산권 침해물품\n\n[핵심 구분: '변질된' vs '변질될 우려가 있는']\n이 유형에서 가장 중요한 구분은 '변질될 우려가 있는 물품'은 반송·폐기 명령 대상이 아니라는 점이다. '우려' 단계는 아직 변질되지 않은 상태이므로 관세법 제160조 제1항의 명령 대상 요건을 충족하지 못한다. 반면 '부패되거나 변질된 물품'은 이미 상태가 훼손된 물품으로 명령 대상이 된다.\n\n[반송·폐기 명령 절차]\n세관장의 반송·폐기 명령을 받은 화주·반입자·그 위임을 받은 자는 자기 비용으로 폐기 또는 반송하여야 한다. 명령 불이행 물품 중 공익상 방치가 곤란한 경우에는 행정대집행법에 따라 보세구역 운영인 또는 화물관리인 등에게 폐기하게 할 수 있다(행정대집행). 폐기 후 잔존물에는 잔존물의 성질과 수량에 따라 관세를 부과한다.",
      "trapAnalysis": "이 문제의 함정은 '변질될 우려가 있는 물품'을 반송·폐기 명령 대상에 포함시키는 것이다. '우려'가 있는 단계(아직 변질 전)를 법정 명령 대상처럼 기술하면 틀린 서술이다. 실제 법정 대상은 '부패되거나 변질된 물품'이며, 이미 상태가 훼손된 것이어야 한다. 이와 혼동되기 쉬운 규정이 '보세구역외장치 허가 대상 중 부패·변질의 우려가 있는 물품'(관세법 제156조)인데, 보세구역외 장치는 '변질 우려' 단계에서 허가를 받아 보호 조치를 취하는 것이고, 반송·폐기 명령은 이미 '변질된' 물품에 내리는 것이다. 두 규정의 '변질 우려 vs 변질된' 구분을 혼동하지 않도록 주의해야 한다.",
