      "answer": [4],
      "conceptExplanation": "「보세화물 입출항 하선 하기 및 적재에 관한 고시」에 따른 화물운송주선업자 업무감독 및 행정제재 절차는 다음과 같다.\n\n[업무감독]\n세관장은 등록된 화물운송주선업자의 본사 또는 영업소에 대하여 매년 단위로 자체계획을 수립하여 등록사항 변동 여부 등에 대한 업무점검을 할 수 있다.\n\n[행정제재 유형과 위원회 심의 요건]\n화물운송주선업자에 대한 행정제재는 경고처분·업무정지·등록취소로 구분된다. 이 중 '경고처분'은 위원회 심의 절차 없이 세관장이 직접 처분한다. 반면 '업무정지'나 '등록취소'의 경우에는 세관장(본부세관은 국장)을 위원장으로 하는 5명 이상의 위원회를 구성하여 심의한 후 결정하여야 한다. 2023년 11번 ④는 '경고처분'에도 위원회 심의가 필요한 것처럼 서술하여 정답이 됐다.\n\n[업무정지 기간 하향 조정]\n관세행정 발전에 기여한 사람으로서 관세채권의 확보 등에 어려움이 없는 경우에는 기준일수의 50% 이내에서 업무정지기간을 하향 조정할 수 있다. 이 경우 최소 업무정지기간은 5일 이상이어야 한다(5일 미만으로 줄일 수 없음).\n\n[사전 의견청취 의무]\n세관장이 등록취소 또는 업무정지를 하려는 때에는 사전에 화물운송주선업자에게 통보하여 의견을 청취해야 한다(청문 절차).\n\n[결격사유 관련]\n화물운송주선업자의 등록취소 후 3년이 경과하지 않은 자는 화물운송주선업자로 재등록할 수 없다(결격사유). 이는 보세운송업자의 결격기간(등록취소 후 2년)과 구별해야 한다.",
      "trapAnalysis": "이 문제의 핵심 함정은 ④처럼 '경고처분'에도 위원회 심의 절차를 거쳐야 한다고 서술하는 것이다. 실제로는 경고처분은 위원회 심의 없이 세관장이 직접 처분하고, 업무정지·등록취소에만 위원회 심의가 적용된다. 또 다른 함정은 업무정지 하향 조정 시 '최소 5일 이상'이라는 하한 규정이다. '최소 기간 제한 없이 50% 이내로 줄일 수 있다'는 식으로 서술하거나, 반대로 '최소 10일 이상'으로 숫자를 바꾸는 형태로 출제될 수 있다. 또한 '등록취소·업무정지 처분 시 청문'(2021년 19번 확인)은 맞는 규정이지만 '경고처분에도 청문 필요'처럼 대상을 확장하면 틀린 서술이 된다.",
      "answerKey": "정답은 ④(2023년 11번). 경고처분을 하려는 경우에는 세관장(본부세관은 국장)을 위원장으로 하는 5명 이상의 위원회를 구성하여 심의할 필요가 없다. 위원회 심의 절차는 업무정지·등록취소 처분 시에 해당하는 것이며, 경고처분은 위원회 심의 없이 세관장이 직접 처분하므로 ④가 틀린 설명이다. ①(매년 단위 업무점검), ②(임원·직원·사용인 위반 시 행정제재), ③(관세행정 기여자 기준일수 50% 이내 하향, 최소 5일), ⑤(등록취소·업무정지 시 사전 의견청취)는 모두 맞는 설명이다.",
